<?php
function sp_terminal_delivery($o){return in_array($o['platform_status'],['Delivered','Completed'],true);}
function sp_manual_statuses($o){return sp_terminal_delivery($o)?['Return / Refund']:['To Ship','Shipped','Delivered','Completed','Cancelled','Failed Delivery','Return / Refund'];}
function sp_assert_manual($o,$status){if(sp_terminal_delivery($o)&&$status!=='Return / Refund')throw new Exception('Delivered / Completed status is locked. Only Return / Refund can be reported; actual returned stock is received in Inflow.');}
function sp_assert_unshipped($o){if($o['posting']!=='Not Posted'||!in_array($o['platform_status'],['To Ship','Unpaid','Needs Checking','Cancelled'],true)||om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$o['id']])->fetchColumn())throw new Exception('Dispatch history exists. Receive an actual returned parcel in Inflow; do not release as pre-dispatch cancellation.');if(in_array(oa_reported($o)['status'],['Shipped','Delivered','Completed','Failed Delivery','Return / Refund'],true))throw new Exception('An earlier platform outcome indicates possible dispatch. Reconcile its posting before releasing this cancellation.');$refs=or_numbers($o['platform'],$o['order_no']);$marks=implode(',',array_fill(0,count($refs),'?'));if(om_query("SELECT COUNT(*) FROM outflows WHERE platform=? AND type='Order' AND qty>0 AND order_id IN ($marks)",array_merge([$o['platform']],$refs))->fetchColumn())throw new Exception('A legacy order outflow exists. Reconcile its dispatch before changing reservations.');}
function sp_release_cancel($o,$upload=null,$source='Confirmed status upload'){
 sp_assert_unshipped($o);$held=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn();om_release_all($o['id'],'Cancellation confirmed · reservation released');om_event($o['id'],$upload,'Pre-dispatch cancellation resolved',['source'=>$source,'before_status'=>$o['platform_status'],'after_status'=>'Cancelled','released_units'=>$held,'physical_delta'=>0,'stock_changed'=>false,'resolution'=>'Resolved; reservation released']);return $held;
}
function sp_pending_plan($platform){om_require();stock_platform($platform);$rows=[];foreach(om_query("SELECT * FROM om_orders WHERE platform=? AND posting='Not Posted' ORDER BY id",[$platform]) as $o){if(!oc_pending_cancellation($o))continue;try{sp_assert_unshipped($o);}catch(Throwable $e){continue;}$report=oa_reported($o);$rows[]=['id'=>(int)$o['id'],'order'=>$o['order_no'],'revision'=>(int)$o['revision'],'reported_snapshot'=>$report['snapshot'],'reserved'=>(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn()];}return ['platform'=>$platform,'rows'=>$rows,'digest'=>hash('sha256',json_encode([$platform,$rows]))];}
function sp_resolve_pending($platform,$digest,$ack){om_require();if(!$ack)throw new Exception('Review and acknowledge the listed cancellations first.');return process_transaction(function()use($platform,$digest){unset($GLOBALS['OA_REPORTS'],$GLOBALS['OM_RESERVED']);$plan=sp_pending_plan($platform);if(!$plan['rows']||!hash_equals($plan['digest'],(string)$digest))throw new Exception('Pending cancellations changed. Refresh and review again.');$released=0;foreach($plan['rows'] as $row){$o=om_order($row['id'],true);$released+=sp_release_cancel($o,null,'Previously confirmed platform cancellation report');om_query("UPDATE om_orders SET platform_status='Cancelled',monitoring='Resolved',status_changed_at=NOW(),exception_text='',revision=revision+1 WHERE id=?",[$o['id']]);}audit('Resolve reported pre-dispatch cancellations','Order Monitoring',$platform,count($plan['rows']).' orders; '.$released.' reserved pcs released; physical stock unchanged.');om_alert_refresh();return ['orders'=>count($plan['rows']),'released'=>$released];});}
function sp_pending_panel($platform){if(!om_allowed())return;$p=sp_pending_plan($platform);if(!$p['rows'])return;echo '<section class="card"><h3>Previously Reported Cancellations</h3><p>'.count($p['rows']).' cancelled orders have no recorded dispatch but still need resolution. Apply the current cancellation rule to release their reservations. Physical stock will not increase.</p>';om_table(['Order ID','Reserved Qty','On confirmation'],array_map(fn($r)=>[$r['order'],$r['reserved'].' pcs','Cancelled · Resolved · reserved 0'],array_slice($p['rows'],0,10)));if(count($p['rows'])>10)echo '<p>Showing first 10; confirmation covers all '.count($p['rows']).' eligible orders in this platform.</p>';om_form('om_resolve_reported_cancellations',['platform'=>$platform,'digest'=>$p['digest']]);echo '<label class="oi-ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed these previously reported cancellations and the reservation-only effect.</label><button class="btn secondary">Resolve Reported Cancellations · Release Reservations</button></form></section>';}
